(gen_random_uuid(), 'Financial Assistance For Purchase Of Stationery', 'Provides help for purchase of stationery to SC/ST/OBC/Minorities Students of 1st to 12th class.', 'Social welfare & Empowerment', '{"target_group": ["Scheduled Caste", "Scheduled Tribe", "OBC", "Minorities", "Students"], "education_required": "1st to 12th class", "special_conditions": ["Studying in Government or Aided schools"]}'::jsonb, 'Financial assistance for stationery purchase', ARRAY['Caste certificate', 'School certificate', 'Identity proof'], 'https://www.myscheme.gov.in/schemes/fafps', 'Delhi', 'Social Welfare Department'),

